/* ROVO Control Center V5 styles */
:root {color-scheme:dark}
body,.v-application{font-family:'DM Sans',Inter,system-ui,-apple-system,'Segoe UI',sans-serif!important;}
.v-application .v-main{background:#09111e!important}
.v-application .v-main .v-container {max-width:1480px!important}
.rx{--bg:#09111e;--card:#111d2e;--card2:#162338;--line:#26364b;--muted:#92a3b9;--txt:#edf5ff;--mint:#78ebd4;--blue:#82adff;--amber:#f6c77c;--good:#55dca7;color:var(--txt);width:100%;padding:12px 8px 38px;box-sizing:border-box;font-size:14px;line-height:1.5}
.rx *,.rx *:before,.rx *:after{box-sizing:border-box}
.rx button,.rx input,.rx select{font:inherit}.rx button{cursor:pointer}
.rx a{text-decoration:none}
.rx-head{display:flex;gap:16px;align-items:flex-start;justify-content:space-between;margin-bottom:23px;flex-wrap:wrap}
.rx-kicker{font-size:10px;letter-spacing:2.3px;color:var(--mint);font-weight:800;text-transform:uppercase}
.rx h1{font-size:clamp(26px,3.2vw,38px);letter-spacing:-1.25px;font-weight:800;line-height:1.18;margin:6px 0 8px}
.rx-sub{color:var(--muted);font-size:13px;max-width:680px;line-height:1.6}
.rx-chip{display:inline-flex;align-items:center;gap:8px;border:1px solid #304259;color:#bbccde;background:#162337;border-radius:999px;padding:7px 11px;font-size:11px;font-weight:700;white-space:nowrap}
.rx-chip.ok{background:#10372f;color:#7fe7c1;border-color:#235e4d}
.rx-chip.warn{background:#3c2d1d;color:#f1c580;border-color:#6c512f}
.rx-dot{width:7px;height:7px;border-radius:50%;background:#869ab2;display:inline-block;flex:none}
.rx-chip.ok .rx-dot{background:#58d9a5}.rx-chip.warn .rx-dot{background:#e9ae55}
.rx-grid{display:grid;gap:14px;grid-template-columns:repeat(12,minmax(0,1fr))}
.rx-span-12{grid-column:span 12}.rx-span-8{grid-column:span 8}.rx-span-7{grid-column:span 7}.rx-span-6{grid-column:span 6}.rx-span-5{grid-column:span 5}.rx-span-4{grid-column:span 4}.rx-span-3{grid-column:span 3}
.rx-panel{border:1px solid var(--line);background:linear-gradient(160deg,#142237,#101a2b);border-radius:20px;padding:22px;min-width:0;box-shadow:0 12px 26px #03091318}
.rx-panel.strong{background:radial-gradient(ellipse at 83% 13%,#1d505b 0%,#17283b 29%,#112034 58%,#101b2b 100%);border-color:#305163}
.rx-panel.flat{background:#101b2c}
.rx-panel-head{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:15px}
.rx-panel h2,.rx-section-title{font-size:15px;letter-spacing:-.3px;font-weight:800;margin:0}
.rx-small{font-size:11px;color:var(--muted);line-height:1.5}
.rx-label{font-size:12px;color:var(--muted)}
.rx-big{font-size:29px;letter-spacing:-1px;line-height:1.2;font-weight:800}
.rx-xl{font-size:clamp(31px,3.6vw,46px);letter-spacing:-1.7px;font-weight:800;line-height:1.2}
.rx-flex{display:flex;align-items:center;gap:12px}.rx-between{display:flex;align-items:center;justify-content:space-between;gap:12px}.rx-wrap{flex-wrap:wrap}.rx-col{display:flex;flex-direction:column;gap:13px}
.rx-icon{height:41px;width:41px;background:#193344;color:var(--mint);border:1px solid #2b5960;border-radius:14px;display:grid;place-items:center;flex:none}
.rx-button{border:1px solid #36506a;border-radius:12px;padding:11px 15px;color:#dceaf8;background:#1a2b42;display:inline-flex;gap:9px;align-items:center;justify-content:center;font-size:12px;font-weight:750;min-height:42px;transition:.16s background,.16s transform}
.rx-button:hover{background:#243d57;transform:translateY(-1px)}
.rx-button.primary{background:#79e7d6;border-color:#79e7d6;color:#0d3238}.rx-button.primary:hover{background:#a0f7e8}
.rx-button.soft{background:#172638}.rx-button.danger{background:#362533;border-color:#6b3d54;color:#ffbecd}
.rx-button:disabled{opacity:.4;cursor:not-allowed}.rx-button.active{border-color:#68e4d0;color:#83eedc;background:#17413f}
.rx-buttons{display:flex;gap:9px;flex-wrap:wrap}
.rx-input,.rx-select{background:#0c1828;color:#f1f8ff;border:1px solid #314761;border-radius:12px;padding:11px 12px;width:100%;min-width:0;outline:none}
.rx-input:focus,.rx-select:focus{border-color:#73dace;box-shadow:0 0 0 3px #4ac4bb18}
.rx-range{width:100%;accent-color:#79e7d6;cursor:pointer;min-height:26px}
.rx-field{display:flex;flex-direction:column;gap:7px}.rx-field label{font-size:12px;color:#c4d5e4;font-weight:700}
.rx-progress{height:8px;border-radius:99px;background:#2a394e;overflow:hidden}.rx-progress>span{height:100%;display:block;border-radius:99px;background:linear-gradient(90deg,#438da6,#7ee9d5)}
.rx-rule{height:1px;background:#2b3b50;margin:18px 0}
.rx-row{display:flex;gap:12px;align-items:center;justify-content:space-between;padding:12px 0;border-bottom:1px solid #26354a;min-width:0}
.rx-row:last-child{border-bottom:0}.rx-row strong{font-size:13px}.rx-row .rx-small{margin-top:2px}
.rx-banner{display:flex;align-items:center;gap:9px;border-radius:12px;border:1px solid #575037;background:#332a1b;color:#f2d6a6;padding:11px 13px;font-size:12px;line-height:1.5;margin-bottom:15px}
.rx-banner.mint{background:#153334;border-color:#235c5b;color:#98e5da}
.rx-note{font-size:11px;color:var(--muted);margin-top:13px;line-height:1.65}
.rx-robot-area{min-width:190px;min-height:178px;display:grid;place-items:center;position:relative}
.rx-robot{width:175px;height:132px;border:7px solid #556f86;border-radius:38px;background:#050d17;box-shadow:0 0 0 3px #223e52,0 28px 48px #041019a9,inset 0 0 26px #1d455d;display:flex;justify-content:center;align-items:center;gap:37px;position:relative}
.rx-eye{height:34px;width:23px;border-radius:99px;background:#81f4e4;box-shadow:0 0 18px #6eebd0a8;animation:rx-blink 7s infinite}
.rx-smile{height:10px;width:29px;border-bottom:3px solid #7ce6d9;border-radius:0 0 99% 99%;position:absolute;bottom:20px;left:calc(50% - 14px)}
@keyframes rx-blink{0%,43%,45%,100%{transform:scaleY(1)}44%{transform:scaleY(.12)}}
.rx-spark{position:absolute;border:1px solid #296577;border-radius:50%;width:216px;height:216px;opacity:.4;pointer-events:none}
.rx-hero{display:flex;align-items:center;justify-content:space-between;gap:24px;min-height:230px}
.rx-hero-copy{flex:1;max-width:540px}.rx-hero-title{font-size:clamp(23px,3vw,35px);line-height:1.2;font-weight:800;letter-spacing:-1px;margin:10px 0}
.rx-stat-value{font-size:clamp(22px,2.4vw,29px);font-weight:800;letter-spacing:-.8px;margin:9px 0 3px;white-space:nowrap}
.rx-quick{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px}
.rx-quick-btn{background:#14263a;border:1px solid #2c425b;border-radius:15px;padding:17px 12px;text-align:left;display:flex;align-items:center;gap:12px;color:var(--txt);min-height:74px}
.rx-quick-btn:hover{border-color:#68cbbc;background:#19374a}.rx-quick-btn .v-icon{color:var(--mint)}
.rx-camera{width:100%;aspect-ratio:16/9;min-height:230px;border:1px solid #334e63;border-radius:16px;overflow:hidden;position:relative;background:radial-gradient(ellipse at 48% 35%,#1e354d,#0b1523 70%);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:11px;color:#96abc2}
.rx-camera img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain}
.rx-camera .rx-corner{position:absolute;inset:21px;pointer-events:none;border:1px solid #4d8d91b0;border-radius:8px;opacity:.3}
.rx-chatbox{height:368px;display:flex;flex-direction:column;gap:12px;overflow:auto;background:#0b1727;border:1px solid #293c52;border-radius:15px;padding:17px}
.rx-bubble{border:1px solid #2d4257;border-radius:15px;background:#1a2a40;max-width:82%;align-self:flex-start;padding:11px 14px;font-size:13px;white-space:pre-wrap;overflow-wrap:anywhere}
.rx-bubble.me{background:#164641;border-color:#27675d;align-self:flex-end}.rx-bubble small{display:block;font-weight:800;color:#8fb6bf;font-size:10px;margin-bottom:4px}
.rx-face-preview{height:198px;display:grid;place-items:center;border:1px solid #2d4658;background:radial-gradient(circle at 50% 15%,#18364e,#081322 72%);border-radius:16px}
.rx-monitor{font:11px/1.8 ui-monospace,Consolas,monospace;background:#081322;border:1px solid #294053;border-radius:13px;padding:14px;max-height:235px;overflow:auto;color:#add0e0}
.rx-bullet{height:8px;width:8px;border-radius:50%;background:#6f8298;display:inline-block}.rx-bullet.good{background:#6bd8a9}.rx-bullet.warn{background:#e1b46d}
.rx-choice{display:flex;flex-wrap:wrap;gap:8px}.rx-choice button{border:1px solid #35506a;background:#18283d;color:#cbd8e8;padding:9px 13px;border-radius:11px;font-size:12px}.rx-choice button.active{background:#164942;border-color:#65caba;color:#80f4df}
.rx-divider-title{font-size:12px;font-weight:800;color:#c2d3e2;margin:18px 0 10px}
@media(max-width:1100px){.rx-span-8,.rx-span-7,.rx-span-5,.rx-span-4,.rx-span-3{grid-column:span 6}.rx-quick{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:740px){.rx{padding:6px 2px 26px}.rx-span-8,.rx-span-7,.rx-span-6,.rx-span-5,.rx-span-4,.rx-span-3{grid-column:span 12}.rx-panel{padding:17px;border-radius:17px}.rx-hero{flex-direction:column;align-items:flex-start}.rx-robot-area{align-self:center}.rx-chatbox{height:310px}}
@media(max-width:440px){.rx-quick{grid-template-columns:1fr 1fr}.rx-quick-btn{flex-direction:column;align-items:flex-start;min-height:95px}.rx-quick-btn .rx-small{font-size:10px}.rx-buttons .rx-button{flex:1}.rx-head{gap:9px}}
